'use strict';

const CR = 0x0d;
const LF = 0x0a;
const QUOTE = 0x22;
const SPACE = 0x20;
const BOM = 0xfeff;
const EOF = -1;

// Parser states.
const RECORD_START = 0; // nothing of the current record has been read yet
const FIELD_START = 1; // a delimiter has just been read
const UNQUOTED = 2;
const QUOTED = 3;
const AFTER_QUOTE = 4; // a `"` inside a quoted field: the closing quote, or the first half of `""`

/**
 * @typedef {object} ParseOptions
 * @property {string} [delimiter=','] One character other than `"`, CR and LF.
 * @property {boolean} [header=false] Use the first record as column names and return objects.
 * @property {boolean} [skipEmptyLines=false] Drop lines that contain no characters at all.
 */

/**
 * @typedef {object} StringifyOptions
 * @property {string} [delimiter=','] One character other than `"`, CR and LF.
 * @property {'\r\n' | '\n'} [eol='\r\n'] Written after every record, including the last.
 * @property {string[]} [header] Column names. Written as the first record; lets rows be objects.
 */

/** Malformed CSV input. `line` and `column` are 1-based; columns count UTF-16 code units. */
class CsvError extends Error {
  /**
   * @param {string} message
   * @param {number} line
   * @param {number} column
   */
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function describe(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

function show(value) {
  return typeof value === 'string' ? JSON.stringify(value) : describe(value);
}

function checkOptions(options, fn) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError(`${fn}: options must be an object, got ${describe(options)}`);
  }
}

function checkDelimiter(delimiter, fn) {
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `${fn}: options.delimiter must be one character other than '"', CR and LF, got ${show(delimiter)}`,
    );
  }
  return delimiter.charCodeAt(0);
}

function checkBoolean(value, name, fn) {
  if (typeof value !== 'boolean') {
    throw new TypeError(`${fn}: options.${name} must be a boolean, got ${describe(value)}`);
  }
  return value;
}

function toObject(columns, values) {
  const object = {};
  for (let k = 0; k < columns.length; k++) {
    const name = columns[k];
    if (name === '__proto__') {
      // Plain assignment would call the prototype setter instead of creating the key.
      Object.defineProperty(object, name, {
        value: values[k],
        enumerable: true,
        writable: true,
        configurable: true,
      });
    } else {
      object[name] = values[k];
    }
  }
  return object;
}

/**
 * Incremental CSV state machine. `parse` feeds it the whole text at once and
 * `createParser` feeds it chunk by chunk, so both produce the same records
 * and errors by construction. All state needed to resume lives on the
 * instance; earlier chunks are never kept or re-read.
 */
class Parser {
  constructor(options, fn) {
    checkOptions(options, fn);
    const { delimiter = ',', header = false, skipEmptyLines = false } = options;
    this.delimiter = checkDelimiter(delimiter, fn);
    this.header = checkBoolean(header, 'header', fn);
    this.skipEmptyLines = checkBoolean(skipEmptyLines, 'skipEmptyLines', fn);

    this.columns = null; // header names, once the header record has been read
    this.seen = this.header ? new Set() : null; // non-null only while reading the header record

    this.state = RECORD_START;
    this.started = false; // whether any input has arrived, for the BOM check
    this.afterCR = false; // the last character read was a CR, so an LF now completes a CRLF
    this.line = 1; // position of the next character to read
    this.column = 1;
    this.recordLine = 1; // line where the current record starts
    this.fieldLine = 1; // position where the current field starts
    this.fieldColumn = 1;
    this.field = '';
    this.record = [];
  }

  /** Reads `chunk` and appends every record it completes to `out`. */
  feed(chunk, out) {
    const n = chunk.length;
    const delimiter = this.delimiter;
    let i = 0;
    if (!this.started && n > 0) {
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) i = 1;
    }
    while (i < n) {
      const c = chunk.charCodeAt(i);
      switch (this.state) {
        case RECORD_START:
          if (this.afterCR) {
            this.afterCR = false;
            if (c === LF) {
              // Second half of a CRLF that has already ended the previous line.
              i++;
              break;
            }
          }
          if (this.skipEmptyLines && (c === CR || c === LF)) {
            this.lineBreak(c);
            i++;
            break;
          }
          this.recordLine = this.line;
          this.fieldLine = this.line;
          this.fieldColumn = this.column;
          this.state = FIELD_START;
        // falls through
        case FIELD_START:
          if (c === QUOTE) {
            this.state = QUOTED;
            this.column++;
            i++;
            break;
          }
          this.state = UNQUOTED;
        // falls through
        case UNQUOTED: {
          let j = i;
          while (j < n) {
            const d = chunk.charCodeAt(j);
            if (d === delimiter || d === CR || d === LF) break;
            j++;
          }
          this.field += chunk.slice(i, j);
          this.column += j - i;
          i = j;
          if (i < n) {
            this.endField(chunk.charCodeAt(i), out);
            i++;
          }
          break;
        }
        case QUOTED:
          i = this.readQuoted(chunk, i);
          break;
        case AFTER_QUOTE:
          if (c === QUOTE) {
            this.field += '"';
            this.column++;
            this.state = QUOTED;
          } else if (c === delimiter || c === CR || c === LF) {
            this.endField(c, out);
          } else {
            throw new CsvError(
              `Unexpected character ${JSON.stringify(chunk[i])} after a closing quote; expected a delimiter or a line break`,
              this.line,
              this.column,
            );
          }
          i++;
          break;
      }
    }
  }

  /** Signals the end of input and appends the final record, if any, to `out`. */
  finish(out) {
    if (this.state === QUOTED) {
      throw new CsvError('Quoted field is never closed', this.fieldLine, this.fieldColumn);
    }
    if (this.state !== RECORD_START) this.endField(EOF, out);
  }

  /** Consumes quoted-field content up to and including the next `"`; returns the new index. */
  readQuoted(chunk, start) {
    const n = chunk.length;
    let { line, column, afterCR } = this;
    let j = start;
    for (; j < n; j++) {
      const c = chunk.charCodeAt(j);
      if (c === QUOTE) break;
      if (c === LF) {
        if (!afterCR) line++;
        column = 1;
        afterCR = false;
      } else if (c === CR) {
        line++;
        column = 1;
        afterCR = true;
      } else {
        column++;
        afterCR = false;
      }
    }
    this.field += chunk.slice(start, j);
    if (j < n) {
      column++;
      afterCR = false;
      this.state = AFTER_QUOTE;
      j++;
    }
    this.line = line;
    this.column = column;
    this.afterCR = afterCR;
    return j;
  }

  /** Ends the current field at `terminator`: the delimiter, CR, LF or EOF. */
  endField(terminator, out) {
    const value = this.field;
    this.field = '';
    if (this.seen !== null) {
      if (this.seen.has(value)) {
        throw new CsvError(`Duplicate header name ${JSON.stringify(value)}`, this.fieldLine, this.fieldColumn);
      }
      this.seen.add(value);
    }
    this.record.push(value);
    if (terminator === this.delimiter) {
      this.column++;
      this.fieldLine = this.line;
      this.fieldColumn = this.column;
      this.state = FIELD_START;
      return;
    }
    this.endRecord(out);
    if (terminator !== EOF) this.lineBreak(terminator);
    this.state = RECORD_START;
  }

  endRecord(out) {
    const record = this.record;
    this.record = [];
    if (!this.header) {
      out.push(record);
    } else if (this.columns === null) {
      this.columns = record;
      this.seen = null;
    } else if (record.length !== this.columns.length) {
      throw new CsvError(
        `Record has ${record.length} field(s) but the header has ${this.columns.length}`,
        this.recordLine,
        1,
      );
    } else {
      out.push(toObject(this.columns, record));
    }
  }

  lineBreak(c) {
    this.line++;
    this.column = 1;
    this.afterCR = c === CR;
  }
}

/**
 * Parses CSV text.
 *
 * @param {string} text
 * @param {ParseOptions} [options]
 * @returns {Array<string[] | Record<string, string>>} Arrays of fields, or objects keyed by
 *   column name when `options.header` is true.
 * @throws {TypeError} If `text` is not a string or an option is invalid.
 * @throws {CsvError} If the input is malformed.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`parse: text must be a string, got ${describe(text)}`);
  }
  const parser = new Parser(options, 'parse');
  const records = [];
  parser.feed(text, records);
  parser.finish(records);
  return records;
}

/**
 * Creates a streaming parser. Chunks may split the input anywhere; the records
 * and errors are the same as `parse` gives for the concatenated input.
 * Once `end()` has been called or either method has thrown, both methods throw.
 *
 * @param {ParseOptions} [options]
 * @returns {{ write(chunk: string): Array<string[] | Record<string, string>>,
 *             end(): Array<string[] | Record<string, string>> }}
 *   `write` returns the records whose terminating line break is in `chunk`;
 *   `end` returns the last record, if the input does not end with a line break.
 * @throws {TypeError} If an option is invalid.
 */
function createParser(options = {}) {
  const parser = new Parser(options, 'createParser');
  let closed = false;

  function assertOpen(method) {
    if (closed) {
      throw new Error(`${method}: the parser has already ended or failed; create a new parser`);
    }
  }

  return {
    write(chunk) {
      assertOpen('write');
      try {
        if (typeof chunk !== 'string') {
          throw new TypeError(`write: chunk must be a string, got ${describe(chunk)}`);
        }
        const records = [];
        parser.feed(chunk, records);
        return records;
      } catch (err) {
        closed = true;
        throw err;
      }
    },
    end() {
      assertOpen('end');
      closed = true;
      const records = [];
      parser.finish(records);
      return records;
    },
  };
}

function fieldText(value, row, index) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value === null || value === undefined) return '';
  throw new TypeError(
    `stringify: rows[${row}] field ${index} must be a string, number, boolean, null or undefined, got ${describe(value)}`,
  );
}

function needsQuotes(text, delimiter) {
  const n = text.length;
  if (n === 0) return false;
  if (text.charCodeAt(0) === SPACE || text.charCodeAt(n - 1) === SPACE) return true;
  for (let k = 0; k < n; k++) {
    const c = text.charCodeAt(k);
    if (c === delimiter || c === QUOTE || c === CR || c === LF) return true;
  }
  return false;
}

function quote(text) {
  return `"${text.replace(/"/g, '""')}"`;
}

function formatRecord(values, delimiter, row, atStart) {
  const fields = new Array(values.length);
  for (let k = 0; k < values.length; k++) {
    const text = fieldText(values[k], row, k);
    fields[k] = needsQuotes(text, delimiter) ? quote(text) : text;
  }
  // Unquoted, a lone empty field is an empty line, which skipEmptyLines would drop.
  if (fields.length === 1 && fields[0] === '') return '""';
  const line = fields.join(String.fromCharCode(delimiter));
  // parse drops a BOM at the start of its input, so the output must not begin with one.
  if (atStart && line.charCodeAt(0) === BOM) return quote(fields[0]) + line.slice(fields[0].length);
  return line;
}

function rowValues(row, header, index) {
  if (Array.isArray(row)) return row;
  if (header !== null && row !== null && typeof row === 'object') {
    return header.map((name) => (Object.hasOwn(row, name) ? row[name] : undefined));
  }
  throw new TypeError(
    `stringify: rows[${index}] must be an array${header !== null ? ' or an object' : ''}, got ${describe(row)}`,
  );
}

/**
 * Serializes records to CSV text that `parse` reads back unchanged.
 *
 * @param {Array<unknown[] | Record<string, unknown>>} rows Arrays of values, or objects when
 *   `options.header` is given. Values may be strings, numbers, booleans, null or undefined.
 * @param {StringifyOptions} [options]
 * @returns {string} `''` when there is neither a header nor any rows.
 * @throws {TypeError} If `rows`, a row, a value or an option has an unsupported type.
 */
function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) {
    throw new TypeError(`stringify: rows must be an array, got ${describe(rows)}`);
  }
  checkOptions(options, 'stringify');
  const { delimiter = ',', eol = '\r\n' } = options;
  const delimiterCode = checkDelimiter(delimiter, 'stringify');
  if (eol !== '\r\n' && eol !== '\n') {
    throw new TypeError(`stringify: options.eol must be "\\r\\n" or "\\n", got ${show(eol)}`);
  }
  // false and null are accepted as "no header" so one options object can be shared with parse.
  const header = options.header === undefined || options.header === false ? null : options.header;
  if (header !== null) {
    if (!Array.isArray(header)) {
      throw new TypeError(`stringify: options.header must be an array of strings, got ${describe(header)}`);
    }
    header.forEach((name, k) => {
      if (typeof name !== 'string') {
        throw new TypeError(`stringify: options.header[${k}] must be a string, got ${describe(name)}`);
      }
    });
  }

  const lines = [];
  if (header !== null) lines.push(formatRecord(header, delimiterCode, 'header', true));
  for (let r = 0; r < rows.length; r++) {
    lines.push(formatRecord(rowValues(rows[r], header, r), delimiterCode, r, lines.length === 0));
  }
  return lines.length === 0 ? '' : lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

