const assert = require('node:assert/strict');
const { stringify } = require('../src/csv');

describe('stringify: arguments', () => {
  it('throws TypeError when rows is not an array', () => {
    for (const rows of [undefined, null, 'a,b', { 0: ['a'] }]) {
      assert.throws(() => stringify(rows), TypeError, `rows: ${String(rows)}`);
    }
  });

  it('throws TypeError for a row that is not an array when there is no header', () => {
    for (const row of [{ a: '1' }, null, 'a', 1]) {
      assert.throws(() => stringify([['ok'], row]), TypeError, `row: ${String(row)}`);
    }
  });

  it('throws TypeError for an invalid delimiter', () => {
    for (const delimiter of ['', ',,', '"', '\r', '\n', 1, null]) {
      assert.throws(() => stringify([['a']], { delimiter }), TypeError, `delimiter: ${JSON.stringify(delimiter)}`);
    }
  });

  it("throws TypeError for an eol other than '\\r\\n' or '\\n'", () => {
    for (const eol of ['\r', '', ' ', '\n\r', 1, null]) {
      assert.throws(() => stringify([['a']], { eol }), TypeError, `eol: ${JSON.stringify(eol)}`);
    }
  });

  it('throws TypeError when options is not an object', () => {
    assert.throws(() => stringify([['a']], null), TypeError);
  });

  it('ignores options it does not use, so options can be shared with parse', () => {
    assert.equal(stringify([['a']], { skipEmptyLines: true }), 'a\r\n');
  });
});

describe('stringify: records and values', () => {
  it('returns an empty string for no rows', () => {
    assert.equal(stringify([]), '');
  });

  it('joins fields with the delimiter and ends every record with CRLF', () => {
    assert.equal(
      stringify([
