    assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  });

  it('writes numbers and booleans with String(), null and undefined as empty fields', () => {
    const row = ['s', 1, 1.5, -0, NaN, Infinity, true, false, null, undefined];
    assert.equal(stringify([row]), 's,1,1.5,0,NaN,Infinity,true,false,,\r\n');
  });

  it('writes a hole in a sparse row as an empty field', () => {
    // eslint-disable-next-line no-sparse-arrays
    assert.equal(stringify([['a', , 'c']]), 'a,,c\r\n');
  });

  it('throws TypeError for any other value type', () => {
    for (const value of [{}, ['a'], Symbol('s'), 1n, () => 'a', new Date(0), new String('a')]) {
