    assert.equal(stringify([['a']], { header: false }), 'a\r\n');
    assert.equal(stringify([['a']], { header: null }), 'a\r\n');
  });

  it('throws TypeError when header is not an array of strings', () => {
    for (const header of [true, 'a,b', { a: 1 }, ['a', 1], [, 'a']]) {
      assert.throws(() => stringify([], { header }), TypeError, `header: ${JSON.stringify(header)}`);
    }
  });

  it('throws TypeError for a null row or an object value in header mode', () => {
    assert.throws(() => stringify([null], { header: ['a'] }), TypeError);
    assert.throws(() => stringify([{ a: { nested: true } }], { header: ['a'] }), TypeError);
  });
});

