assert.deepEqual(parse("name,age\r\nAda,36\r\n"), [["name","age"],["Ada","36"]]);
assert.deepEqual(parse("name,age\nAda,36\n", { header: true }), [{ name: "Ada", age: "36" }]);
assert.equal(stringify([["a,b", "say \"hi\""], [""]]), "\"a,b\",\"say \"\"hi\"\"\"\r\n\"\"\r\n");
